fn gcd_i(mut m: i32, mut n: i32) -> i32 {
    // Both m and n are assumed to be > 0.
    // Use the subtraction-based Euclidean algorithm.
    while m != n {
        if m > n {
            m -= n;
        } else {
            n -= m;
        }
    }
    // When they become equal, that's the GCD.
    m
}

